  if (originalDocsMdxBuildStart === undefined) {
    throw new TypeError("Fumadocs Vite plugin must expose a buildStart hook.");
  }
  let docsMdxBuildStartResult: Promise<unknown> | undefined;
  const docsMdxForBuild = {
